    34	export class PgNotificationRepository implements INotificationRepository {
    35	  async findByRecipientId(recipientId: string): Promise<Notification[]> {
    36	    const result = await pool.query<NotificationRow>(
    37	      'SELECT * FROM notifications WHERE recipient_id = $1 ORDER BY created_at DESC',
    38	      [recipientId],
    39	    );
    40	    return result.rows.map(mapRowToNotification);
    41	  }
