    54	  async create(
    55	    notification: Omit<Notification, 'id' | 'createdAt'>,
    56	  ): Promise<Notification> {
    57	    const id = randomUUID();
    58	    const result = await pool.query<NotificationRow>(
    59	      `INSERT INTO notifications (
    60	        id, recipient_id, type, title, message,
    61	        related_entity_type, related_entity_id, status, created_at, read_at
