    63	      RETURNING *`,
    64	      [
    65	        id,
    66	        notification.recipientId,
    67	        notification.type,
    68	        notification.title,
    69	        notification.message,
    70	        notification.relatedEntityType,
    71	        notification.relatedEntityId,
    72	        notification.status,
    73	        notification.readAt ?? null,
    74	      ],
    75	    );
